const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(v,p){let a=new Float64Array(v.length),k=2/(p+1),e=v[0];for(let i=0;i<v.length;i++){if(i)e=v[i]*k+e*(1-k);a[i]=e}return a}function atr(c,p=14){let a=new Float64Array(c.length);for(let i=p;i<c.length;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(c[j].h-c[j].l,Math.abs(c[j].h-c[j-1].c),Math.abs(c[j].l-c[j-1].c));a[i]=s/p}return a}const C=M.map(x=>x.c),E=ema(C,20),A=atr(M);
