const RAW=[];for(let i=60;i<M.length-1;i++){while(hp+1<H.length&&H[hp+1].t<=M[i].t)hp++;let h=hp-1;if(h<52||!(A[i]>0&&HA[h]>0))continue;let sep=Math.abs(H20[h]-H50[h])/HA[h],bull=HC[h]>H20[h]&&H20[h]>H50[h]&&H20[h]>H20[h-2],bear=HC[h]<H20[h]&&H20[h]<H50[h]&&H20[h]<H20[h-2];if(!bull&&!bear)continue;let hi=Math.max(M[i-1].h,M[i-2].h,M[i-3].h),lo=Math.min(M[i-1].l,M[i-2].l,M[i-3].l),rg=M[i].h-M[i].l;if(!(rg>0))continue;let body=Math.abs(M[i].c-M[i].o)/A[i],pos=(M[i].c-M[i].l)/rg,range=rg/A[i],dist=Math.abs(M[i].c-E[i])/A[i],side=bull&&M[i].c>hi&&M[i].c>E[i]?'BUY':bear&&M[i].c<lo&&M[i].c<E[i]?'SELL':null;if(!side)continue;let swing=side==='BUY'?Math.min(M[i].l,M[i-1].l):Math.max(M[i].h,M[i-1].h),risk=Math.max(A[i]*.65,Math.abs(M[i+1].o-swing))/A[i];RAW.push({i,t:M[i].t,h:new Date(M[i].t).getUTCHours(),side,sep,body,pos,range,dist,risk})}
const BASE={sep:.10,body:.65,pos:.72,range:2,dist:1.5,risk:1.35,extra:[],buyExtra:[]},BASEH=new Set([2,6,12,18,20,22]),BASEBUY=new Set([3,16]);function sel(q){let ex=new Set(q.extra),bx=new Set(q.buyExtra);return RAW.filter(x=>!BASEH.has(x.h)&&!ex.has(x.h)&&!(x.side==='BUY'&&(BASEBUY.has(x.h)||bx.has(x.h)))&&x.sep>=q.sep&&x.body>=q.body&&x.range<=q.range&&x.dist<=q.dist&&x.risk<=q.risk&&(x.side==='BUY'?x.pos>=q.pos:x.pos<=1-q.pos))}
function trades(q){let Sg=new Map(sel(q).map(x=>[x.i,x])),out=[],p=null;for(let i=60;i<M.length;i++){if(p){let b=M[i],sl=p.side==='BUY'?b.l<=p.sl:b.h>=p.sl,tp=p.side==='BUY'?b.h>=p.tp:b.l<=p.tp;if(sl||tp||i-p.ei+1>=10){let px=sl?p.sl:tp?p.tp:b.c,r=p.side==='BUY'?(px-p.en)/p.risk:(p.en-px)/p.risk;out.push({t:M[p.si].t,r,side:p.side});p=null}if(p)continue}let si=i-1,x=Sg.get(si);if(x){let en=M[i].o,swing=x.side==='BUY'?Math.min(M[si].l,M[si-1].l):Math.max(M[si].h,M[si-1].h),risk=Math.max(A[si]*.65,Math.abs(en-swing));if(risk>A[si]*q.risk)continue;let rr=x.side==='BUY'?.85:.8;p={side:x.side,en,risk,sl:x.side==='BUY'?en-risk:en+risk,tp:x.side==='BUY'?en+risk*rr:en-risk*rr,ei:i,si}}}return out}function stat(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(let x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
